import { useEffect, useState } from 'react';

export const TIPS = [
  'Держите эталон и образец на одной высоте — так площадь считается точнее.',
  'Снимайте эталон и образец при одинаковом увеличении: масштаб считается по эталону.',
  'Эталон должен лежать ровно и целиком попадать в кадр, без бликов на краях.',
  'Если эталон не нашёлся автоматически, перетащите четыре угла вручную: лупа поможет попасть точно.',
  'Колёсико мыши меняет масштаб, пробел с перетаскиванием двигает снимок.',
  'Чем выше разрешение снимка, тем меньше погрешность: она равна половине пикселя эталона.',
  'Каждое сохранение отчёта создаёт новую версию, к любой можно вернуться в журнале.',
  'Для сравнения двух образцов оба должны быть откалиброваны: разница считается в миллиметрах.',
];

export function useTip(ms = 9000) {
  const [i, setI] = useState(() => Math.floor(Math.random() * TIPS.length));
  const [out, setOut] = useState(false);
  const next = () => { setOut(true); setTimeout(() => { setI((v) => (v + 1) % TIPS.length); setOut(false); }, 300); };
  useEffect(() => { const t = setInterval(next, ms); return () => clearInterval(t); }, [ms]);
  return { text: TIPS[i]!, out, next };
}
